CREATE TABLE metrics (
    id BIGINT NOT NULL,
    recorded_on DATE NOT NULL,
    reading DOUBLE PRECISION,
    PRIMARY KEY (id, recorded_on)
) PARTITION BY RANGE (recorded_on);
CREATE TABLE metrics_2026 PARTITION OF metrics (reading WITH OPTIONS NOT NULL) FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
CREATE TABLE metrics_2027 PARTITION OF metrics FOR VALUES FROM ('2027-01-01') TO ('2028-01-01');
ALTER TABLE metrics ADD COLUMN device TEXT;
CREATE SEQUENCE metric_numbers START 50;
CREATE FUNCTION touch() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RETURN NEW; END$$;
CREATE OR REPLACE TRIGGER metrics_touch BEFORE UPDATE ON metrics_2026 FOR EACH ROW EXECUTE FUNCTION touch();
CREATE OR REPLACE TRIGGER metrics_touch BEFORE INSERT ON metrics_2026 FOR EACH ROW EXECUTE FUNCTION touch();
